d<-file.path(OUT,'07_sensitivity_analysis');a<-file.path(OUT,'05_LLPS_ligand_correlation');z<-readRDS(file.path(OUT,'00_input_audit/C5_expression_small.rds'));m<-z$metadata;focus<-fread(file.path(OUT,'00_input_audit/candidate_overlap.csv'))$gene;lo<-fread(file.path(a,'leave_gene_out_scores.csv.gz'));lo<-lo[match(m$cell,cell)];expr<-fread(file.path(a,'pseudobulk_ligand_expression.csv.gz'));pm<-fread(file.path(a,'patient_pseudobulk_metadata.csv'));over<-fread(file.path(a,'overlapping_ligands.csv'))$overlap_gene
