safe_cor<-function(x,y,method='pearson'){if(length(x)<4||sd(x)==0||sd(y)==0)NA_real_ else cor(x,y,method=method)}
tech<-m[,.(n=.N,score_nCount_r=safe_cor(LLPS77_AUC,log1p(nCount_RNA)),score_nFeature_r=safe_cor(LLPS77_AUC,log1p(nFeature_RNA))),by=.(specimen_id,patient_id,dataset,clinical_group)];writecsv(tech,file.path(d,'score_depth_confounding.csv'))
ii<-which(m$clinical_group!='Normal');mm<-m[ii];X<-model.matrix(~factor(specimen_id)+log1p(nCount_RNA)+log1p(nFeature_RNA),mm);rs<-lm.fit(X,mm$LLPS77_AUC)$residuals;rr<-rbindlist(lapply(genes,function(g){v<-as.numeric(z$data[g,ii]);rv<-lm.fit(X,v)$residuals;data.table(gene=g,n_cells=length(ii),adjusted_pearson=safe_cor(rs,rv),design_rank=qr(X)$rank,interpretation='Descriptive cell-level residual correlation; specimen fixed effects absorb patient and dataset. No cell-independent P value.')}));writecsv(rr,file.path(d,'pooled_sample_depth_adjusted_descriptive.csv'))
# Paired full/LOO scores reuse exactly the same C5 ranking; original baseline separately retained.
res<-list();k<-0L
for(g in over)for(scoretype in c('reconstructed_full',paste0('without_',g))){sc<-m[,.(patient_id,clinical_group,dataset)];sc[,score:=lo[[scoretype]]];sc<-sc[clinical_group!='Normal',.(score=mean(score)),by=.(patient_id,dataset)];for(th in c(5,10,20)){dd<-merge(expr[gene==g&min_cells==th],sc,by='patient_id');dd<-merge(dd,pm[,.(patient_id,n_cells)],by='patient_id');dd<-dd[n_cells>=th];if(nrow(dd)<5)next;X<-if(uniqueN(dd$dataset)>1)model.matrix(~score+factor(dataset),dd)else model.matrix(~score,dd);b<-p<-NA_real_;df<-nrow(X)-qr(X)$rank;if(qr(X)$rank==ncol(X)&&df>=3&&sd(dd$score)>0&&sd(dd$logCPM)>0){fit<-lm.fit(X,dd$logCPM);se<-sqrt(sum(fit$residuals^2)/df*diag(solve(crossprod(X))));b<-fit$coefficients[2];p<-2*pt(-abs(b/se[2]),df=df)};k<-k+1L;res[[k]]<-data.table(gene=g,score_type=scoretype,min_cells=th,n_patients=nrow(dd),pearson=safe_cor(dd$score,dd$logCPM),spearman=safe_cor(dd$score,dd$logCPM,'spearman'),adjusted_beta=b,adjusted_p=p,residual_df=df)}};r<-rbindlist(res);r[,sensitivity:=ifelse(startsWith(score_type,'without_'),'leave_gene_out','reconstructed_full')];r[,FDR_overlap_family:=p.adjust(adjusted_p,'BH'),by=.(min_cells,sensitivity)];writecsv(r,file.path(d,'pseudobulk_leave_gene_out.csv'))
res<-list();k<-0L
for(g in focus){dd<-merge(expr[gene==g&min_cells==10],pm,by='patient_id');dd<-dd[n_cells>=10];for(left in c('NONE',dd$patient_id)){z<-dd[patient_id!=left];X<-if(uniqueN(z$dataset)>1)model.matrix(~score_mean+factor(dataset),z)else model.matrix(~score_mean,z);df<-nrow(X)-qr(X)$rank;b<-NA_real_;if(nrow(z)>=5&&qr(X)$rank==ncol(X)&&df>=3)b<-lm.fit(X,z$logCPM)$coefficients[2];k<-k+1L;res[[k]]<-data.table(gene=g,left_out=left,n_patients=nrow(z),adjusted_beta=b,pearson=safe_cor(z$score_mean,z$logCPM),spearman=safe_cor(z$score_mean,z$logCPM,'spearman'))}};writecsv(rbindlist(res),file.path(d,'focused_pseudobulk_leave_patient_out.csv'));technical<-m[clinical_group!='Normal',.(mean_log_nCount=mean(log1p(nCount_RNA)),mean_log_nFeature=mean(log1p(nFeature_RNA))),by=patient_id];res<-list();k<-0L
for(g in genes)for(th in c(5,10,20)){dd<-merge(expr[gene==g&min_cells==th],pm,by='patient_id');dd<-merge(dd[n_cells>=th],technical,by='patient_id');if(nrow(dd)<5)next;X<-if(uniqueN(dd$dataset)>1)model.matrix(~score_mean+factor(dataset)+mean_log_nCount+mean_log_nFeature,dd)else model.matrix(~score_mean+mean_log_nCount+mean_log_nFeature,dd);df<-nrow(X)-qr(X)$rank;b<-p<-NA_real_;if(qr(X)$rank==ncol(X)&&df>=3&&sd(dd$logCPM)>1e-8&&det[gene==g&min_cells==th,gene_detected_patients]>=3){fit<-lm.fit(X,dd$logCPM);se<-sqrt(sum(fit$residuals^2)/df*diag(solve(crossprod(X))));b<-fit$coefficients[2];p<-2*pt(-abs(b/se[2]),df=df)};k<-k+1L;res[[k]]<-data.table(gene=g,min_cells=th,n_patients=nrow(dd),model_rank=qr(X)$rank,residual_df=df,adjusted_beta=b,p=p)};q<-rbindlist(res);q[,FDR_all:=p.adjust(p,'BH'),by=min_cells];q[,FDR_focus:=NA_real_];q[gene%in%focus,FDR_focus:=p.adjust(p,'BH'),by=min_cells];writecsv(q,file.path(d,'pseudobulk_dataset_depth_adjusted.csv'));cat('EXTRA SENSITIVITIES COMPLETE\n')
